const unplayableLibrarySongs = `-- name: UnplayableLibrarySongs :many
SELECT t.library_id
FROM tracks t
JOIN library_items li ON li.kind = 'song' AND li.ref = t.id
WHERE t.library_id IS NOT NULL AND t.no_play_params = 1
`

// The songs Apple gave no playParams yet, whatever their album's state now:
// a song is asked for until it has them, so one still a placeholder when its
// album's flag clears (the albums and songs domains run side by side) is not
// left behind with its stand-in name.
func (q *Queries) UnplayableLibrarySongs(ctx context.Context) ([]sql.NullString, error) {
	rows, err := q.db.QueryContext(ctx, unplayableLibrarySongs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []sql.NullString{}
	for rows.Next() {
		var library_id sql.NullString
		if err := rows.Scan(&library_id); err != nil {
			return nil, err
		}
		items = append(items, library_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upcomingLibraryAlbums = `-- name: UpcomingLibraryAlbums :many
SELECT a.library_id, a.is_prerelease, a.release_date, a.catalog_release_date
FROM albums a JOIN library_items li ON li.kind = 'album' AND li.ref = a.id
WHERE a.library_id IS NOT NULL
  AND (a.is_prerelease = 1 OR a.release_date > ?1 OR a.catalog_release_date > ?1)
`

type UpcomingLibraryAlbumsRow struct {
	LibraryID          sql.NullString
	IsPrerelease       int64
	ReleaseDate        string
	CatalogReleaseDate string
}

// Library albums whose release is still ahead: flagged pre-release by Apple
// or dated after the day (?1, "YYYY-MM-DD"; a year alone counts only while
// it is flagged). The incremental sync refreshes them, as it stops at the
// first album it already has.
func (q *Queries) UpcomingLibraryAlbums(ctx context.Context, releaseDate string) ([]UpcomingLibraryAlbumsRow, error) {
	rows, err := q.db.QueryContext(ctx, upcomingLibraryAlbums, releaseDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UpcomingLibraryAlbumsRow{}
	for rows.Next() {
		var i UpcomingLibraryAlbumsRow
		if err := rows.Scan(
			&i.LibraryID,
			&i.IsPrerelease,
			&i.ReleaseDate,
			&i.CatalogReleaseDate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertLibraryAlbum = `-- name: UpsertLibraryAlbum :one
INSERT INTO albums (
    library_id, catalog_id, name, artist_name, artist_library_id, artist_catalog_id,
    artwork_template, release_date, genre, track_count, content_rating, is_single,
    is_prerelease, catalog_release_date, updated_at
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (library_id) DO UPDATE SET
    catalog_id = excluded.catalog_id,
    name = excluded.name,
    artist_name = excluded.artist_name,
    artist_library_id = coalesce(excluded.artist_library_id, albums.artist_library_id),
    artist_catalog_id = coalesce(excluded.artist_catalog_id, albums.artist_catalog_id),
    artwork_template = excluded.artwork_template,
    release_date = excluded.release_date,
    genre = excluded.genre,
    track_count = excluded.track_count,
    content_rating = excluded.content_rating,
    is_single = excluded.is_single,
    is_prerelease = excluded.is_prerelease,
    catalog_release_date = excluded.catalog_release_date,
    credits_checked = CASE WHEN excluded.artist_name <> albums.artist_name OR excluded.catalog_id IS NOT albums.catalog_id THEN 0 ELSE albums.credits_checked END,
    updated_at = excluded.updated_at
RETURNING id
`

type UpsertLibraryAlbumParams struct {
	LibraryID          sql.NullString
	CatalogID          sql.NullString
	Name               string
	ArtistName         string
	ArtistLibraryID    sql.NullString
	ArtistCatalogID    sql.NullString
	ArtworkTemplate    string
	ReleaseDate        string
	Genre              string
	TrackCount         int64
	ContentRating      string
	IsSingle           int64
	IsPrerelease       int64
	CatalogReleaseDate string
	UpdatedAt          int64
}

func (q *Queries) UpsertLibraryAlbum(ctx context.Context, arg UpsertLibraryAlbumParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, upsertLibraryAlbum,
		arg.LibraryID,
		arg.CatalogID,
		arg.Name,
		arg.ArtistName,
		arg.ArtistLibraryID,
		arg.ArtistCatalogID,
		arg.ArtworkTemplate,
		arg.ReleaseDate,
		arg.Genre,
		arg.TrackCount,
		arg.ContentRating,
		arg.IsSingle,
		arg.IsPrerelease,
		arg.CatalogReleaseDate,
		arg.UpdatedAt,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}

